/* ---------- rajzolt pergamen-térkép: tájanként, a kutak fedik fel ---------- */
const MW = 780, MH = 520, MAPC = { done: false, row: 0, h: null, ri: null, land: null, det: null, blank: null, masks: null, comp: null, key: '' };
